export interface CarbonAnalysisEvent {
  type?: string;
  payloadSummary?: {
    error?: unknown;
    message?: unknown;
    partialFailure?: unknown;
  };
}

export interface CarbonJobNotice {
  severity: 'info' | 'success' | 'warning' | 'error';
  message: string;
}

export const CARBON_ANALYSIS_RUNNING_NOTICE: CarbonJobNotice = {
  severity: 'info',
  message: 'Carbon calculation is running. Totals update when the job finishes.',
};

export function carbonAnalysisNoticeFromEvent(
  event: CarbonAnalysisEvent | null | undefined
): CarbonJobNotice | null {
  const type = String(event?.type || '');
  const summary = event?.payloadSummary || {};
  if (type === 'transactions.carbon_analysis.completed') {
    if (summary.partialFailure === true) {
      return {
        severity: 'warning',
        message: 'Carbon calculation finished, but some rows could not be assessed. The screen is loading the rows that were saved.',
      };
    }
    return {
      severity: 'success',
      message: 'Carbon calculation finished. Updated totals are loading.',
    };
  }
  if (type === 'transactions.carbon_analysis.failed') {
    const detail = typeof summary.error === 'string' && summary.error.trim()
      ? summary.error.trim()
      : 'Carbon calculation failed.';
    return {
      severity: 'error',
      message: `${detail} Previous totals stay on screen until a calculation succeeds.`,
    };
  }
  return null;
}

export function documentProcessingNoticeFromEvent(
  event: CarbonAnalysisEvent | null | undefined
): CarbonJobNotice | null {
  const type = String(event?.type || '');
  if (type !== 'document.failed') return null;
  const summary = event?.payloadSummary || {};
  const message = typeof summary.message === 'string' ? summary.message.trim() : '';
  const error = typeof summary.error === 'string' ? summary.error.trim() : '';
  const detail = message || error || 'Document processing failed.';
  return {
    severity: 'error',
    message: `${detail} Previous carbon footprint totals stay on screen.`,
  };
}
